package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;import dalvik.system.DexClassLoader;
/** Recompiles all current Java, lowering lambdas before DX. Fixed packaged resources remain. */
final class FullBuild{
 static File lowerer(Context c)throws Exception{JSONObject info=new JSONObject(AppJavaChat.asset(c,"java-tools/source-lowerer-provenance.json",4000));String sha=info.getString("sha256");if(!sha.matches("[a-f0-9]{64}"))throw new IOException("Identidad de herramienta inválida.");File f=new File(OnDeviceJava.home(c),"source-lowerer-"+sha.substring(0,16)+".jar");if(!f.exists())try(InputStream in=c.getAssets().open("java-tools/source-lowerer.jar")){OnDeviceJava.immutable(f,OnDeviceJava.bytes(in,1000000));}if(!ProjectRuntime.digest(f).equals(sha))throw new IOException("La herramienta cambió.");return f;}
 static CoreBuild.Result prepare(Context c)throws Exception{NaturalCoding.project(c);JSONObject work=JavaProject.working(c);String guard=work.toString(),from=JavaProject.fingerprint(c);Map<String,String> all=JavaProject.files(c,work),old=JavaProject.files(c,new JSONObject());File root=new File(c.getDir("java-project",0),"full-"+UUID.randomUUID()),input=new File(root,"original"),lowered=new File(root,"lowered"),classes=new File(root,"classes"),legacy=new File(root,"legacy");for(File f:new File[]{input,lowered,classes,legacy})if(!f.mkdirs())throw new IOException("No pude preparar la reconstrucción total.");for(Map.Entry<String,String> e:all.entrySet())try(OutputStream out=new FileOutputStream(new File(input,e.getKey()))){out.write(e.getValue().getBytes("UTF-8"));}
 File opt=new File(OnDeviceJava.home(c),"full-opt");opt.mkdirs();ClassLoader compiler=new DexClassLoader(OnDeviceJava.tool(c,"compiler.jar").getAbsolutePath(),opt.getAbsolutePath(),null,c.getClassLoader()),tool=new DexClassLoader(lowerer(c).getAbsolutePath(),opt.getAbsolutePath(),null,compiler);JavaChat.phase("Reconstrucción: resolviendo y convirtiendo las lambdas de todo Java…");int count;try{count=(Integer)tool.loadClass("com.bananalab.tools.SourceLowerer").getMethod("lower",String.class,String.class,String.class).invoke(null,JavaProject.api(c).getAbsolutePath(),input.getAbsolutePath(),lowered.getAbsolutePath());}catch(java.lang.reflect.InvocationTargetException e){throw new IOException("No pude convertir todo Java: "+AndroidRepair.summary(e.getCause()));}
 List<String> args=new ArrayList<>(Arrays.asList("-1.8","-proc:none","-warn:none","-encoding","UTF-8","-bootclasspath",JavaProject.api(c).getAbsolutePath(),"-d",classes.getAbsolutePath()));for(String name:all.keySet())args.add(new File(lowered,name).getAbsolutePath());StringWriter log=new StringWriter();PrintWriter writer=new PrintWriter(log);Class<?> ecj=compiler.loadClass("org.eclipse.jdt.internal.compiler.batch.Main");Object instance=ecj.getConstructor(PrintWriter.class,PrintWriter.class,boolean.class).newInstance(writer,writer,false);JavaChat.phase("Reconstrucción: compilando "+all.size()+" archivos, "+count+" lambdas convertidas…");if(!(Boolean)ecj.getMethod("compile",String[].class).invoke(instance,new Object[]{args.toArray(new String[0])}))throw new IOException("El proyecto no compila: "+log.toString().substring(0,Math.min(4000,log.toString().length())));
 File compiled=new File(classes,"com/bananalab/lite");File[] files=compiled.listFiles();if(files==null||files.length==0)throw new IOException("No hay clases nuevas.");ByteArrayOutputStream api=new ByteArrayOutputStream();try(ZipOutputStream jar=new ZipOutputStream(api)){for(File file:files)if(file.getName().endsWith(".class")){byte[] bytes;try(InputStream in=new FileInputStream(file)){bytes=OnDeviceJava.bytes(in,1000000);}JvmClass parsed=JvmClass.read(bytes);String path="com/bananalab/lite/"+file.getName();if(!parsed.name.equals(path.substring(0,path.length()-6)))throw new IOException("Clase fuera del paquete.");byte[] compatible=JvmClass.legacy(bytes);File dest=new File(legacy,path);dest.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(dest)){out.write(compatible);}ZipEntry entry=new ZipEntry(path);entry.setTime(315619200000L);jar.putNextEntry(entry);jar.write(bytes);jar.closeEntry();}}
 File dex=new File(root,"classes.dex");Class<?> arguments=compiler.loadClass("com.android.dx.command.dexer.Main$Arguments");Object options=arguments.newInstance();arguments.getMethod("parse",String[].class).invoke(options,new Object[]{new String[]{"--output="+dex.getAbsolutePath(),"--no-strict",legacy.getAbsolutePath()}});JavaChat.phase("Reconstrucción: generando un DEX nuevo con todas las clases…");if((Integer)compiler.loadClass("com.android.dx.command.dexer.Main").getMethod("run",arguments).invoke(null,options)!=0)throw new IOException("DX no pudo construir todo Java.");CoreBuild.Result result=new CoreBuild.Result();try(InputStream in=new FileInputStream(dex)){result.dex=OnDeviceJava.bytes(in,16600000);}if(result.dex.length<112||result.dex[6]!='5')throw new IOException("DEX nuevo incompatible.");result.api=api.toByteArray();result.index=CoreBuild.index(all,"0.66").toString().getBytes("UTF-8");result.from=from;result.to=CoreBuild.sha(result.index);result.work=guard;result.sources=all;result.before=new JSONObject();for(String name:all.keySet())if(old.containsKey(name)&&!old.get(name).equals(all.get(name)))result.before.put(name,old.get(name));result.provenance=new JSONObject().put("sha256",CoreBuild.sha(result.api)).put("sourceMapHash",result.to).put("purpose","Full Java rebuild after binding-aware source lowering").toString().getBytes("UTF-8");if(!guard.equals(JavaProject.prefs(c).getString("working","{}"))||!from.equals(JavaProject.fingerprint(c)))throw new IOException("Las fuentes cambiaron durante la reconstrucción.");JavaProject.prefs(c).edit().putString("fullBuildReport","Recompilé "+all.size()+" archivos y "+files.length+" clases; convertí "+count+" lambdas. No reutilicé clases del DEX anterior. Recursos empaquetados conservados.").commit();DeviceApk.erase(root);return result;}
}
